@startuml

class Library {
}

class RegisteredUser {
  + security_deposit : double
  + phone : string
  + email : string
  + mail : string
}

class BorrowableItem {
  + library_code : string
  + location : string
}

class Book {
  + publisher : string
  + authors : string[]
}

class MagazineIssue {
  + publication_date : date
  + publisher : string
}

class MusicCD {
  + publisher : string
  + artist : string
}

class Film {
  + duration : int
  + actors : string[]
  + publisher : string
}

class DVDFilm extends Film {}
class VHSFilm extends Film {}

class Loan {
  + due_date : date
}

class Request {
}

Library "1" -- "*" RegisteredUser : has
Library "1" -- "*" BorrowableItem : has
RegisteredUser "1" -- "*" Loan : makes
Loan "*" -- "1" BorrowableItem : involves
RegisteredUser "0..1" -- "*" Request : sends
Request "*" -- "1" BorrowableItem : for

@enduml

